let map: Map<string, string> | null = null;

/** 一个字的全部读音。不是汉字（或表里没有）返回 undefined */
export function readingsOf(ch: string): string[] | undefined {
  if (!map) {
    map = new Map();
    for (const tok of PACKED.split(' ')) {
      if (tok.length > 1) map.set(tok[0]!, tok.slice(1));
    }
  }
  return map.get(ch)?.split('|');
}
